import {
  DisplayCircleIcon,
  DisplayFlexRCC,
  MitraCard,
  Row,
} from '../../../../../commonStyle/index.style'
import { CustomText } from '../../../../../components'
// import { NotificationManager } from 'react-notifications'
import NumericInput from '../../../../../components/NumericInput'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../lang'
import {
  useRemoveProofPhoto,
  useUploadPoliciesPoofPhoto,
  useSetPoliciesAmount,
} from '../../state/hooks/useInstantPayout'
import { PayoutPhotoStyle } from './index.style'
import { get } from 'lodash'
import { useEffect } from 'react'
import OnlinePaymentCard from '../../../../../components/OnlinePaymentCard'
import ShowSnackbar from '../../../../../components/ShowNotification'
import { INPUT_FILE_TYPE } from '../../../../../constants/file'

function PayoutPhotoSection(props) {
  const { errorField } = props
  const { prefilledData = {} } = props
  const [{ uploadProofPhotoData }, uploadPhotoProof] = useUploadPoliciesPoofPhoto()

  const removePhotoProof = useRemoveProofPhoto()
  const [{ policiesAmount }, updatePoliciesAmount] = useSetPoliciesAmount()
  // const [resetState] = useResetInstantPayoutState()

  useEffect(() => {
    if (prefilledData.amount_paid && !policiesAmount) {
      updatePoliciesAmount(prefilledData.amount_paid)
    }
  }, [prefilledData, updatePoliciesAmount, policiesAmount])

  const handlePaymentAmount = (amount) => {
    if (amount && amount.target.value) {
      updatePoliciesAmount(amount.target.value.match(/\d/g).join(''))
    }
  }

  const handleRemoveProof = (index) => {
    // remove the index from the file
    removePhotoProof(index)
  }

  const handleUpload = (e) => {
    const file = document.getElementById('photo-upload')
    if ('files' in file) {
      if (file.files[0]) {
        if (file.files[0].size >= 1500000) {
          // NotificationManager.error('Ukuran file terlalu besar')
          ShowSnackbar.error({
            visible: true,
            text: 'Ukuran file terlalu besar',
          })
        } else {
          // NotificationManager.info('Pengunggahan dimulai')
          ShowSnackbar.success({
            visible: true,
            text: 'Pengunggahan dimulai',
          })
          const formData = new FormData()
          formData.append('file', file.files[0])
          uploadPhotoProof({
            body: formData,
          })
          e.target.value = null
        }
      }
    }
  }

  const renderCardTitle = (title) => {
    return (
      <CustomText color={AgentColorPallette.black} weight={700} size="16px" bottom="8px">
        {title}
      </CustomText>
    )
  }

  return (
    <PayoutPhotoStyle>
      <CustomText color={AgentColorPallette.black} size="15px" weight={800} bottom="10px">
        {`B. ${LANG_STRINGS.photoProof}`}
      </CustomText>
      <OnlinePaymentCard />
      <MitraCard width="auto" bottom="8px">
        {renderCardTitle(LANG_STRINGS.paymentAmount)}
        <NumericInput
          defaultValue={prefilledData.amount_paid ? prefilledData.amount_paid : false}
          type="amount"
          errorField={errorField}
          name="paymentAmount"
          id="paymentAmount"
          className="payment-amount"
          placeholder="Rp 0"
          displayBorder
          onBlur={handlePaymentAmount}
          onChange={() => {}}
        />
      </MitraCard>
      <MitraCard width="auto">
        {renderCardTitle(LANG_STRINGS.photoOfProofPayment)}
        <Row align="center">
          {!!get(uploadProofPhotoData, 'length', 0) &&
            uploadProofPhotoData.map((proof, index) => (
              <DisplayFlexRCC className="proof-image-container" key={`proof-photo-${index}`}>
                <DisplayCircleIcon
                  className="delete-photo"
                  bgColor={AgentColorPallette.white}
                  color={AgentColorPallette.black}
                  onClick={() => handleRemoveProof(index)}
                >
                  <i className="far fa-trash-alt" />
                </DisplayCircleIcon>
                <img src={proof} alt="Payment Proof" />
              </DisplayFlexRCC>
            ))}
        </Row>
        <Row className="upload-photo-btn" align="center" justify="center">
          <input
            type="file"
            id="photo-upload"
            name="photo-upload"
            onChange={handleUpload}
            accept={INPUT_FILE_TYPE.IMAGE}
          />
          +
        </Row>
      </MitraCard>
    </PayoutPhotoStyle>
  )
}

export default PayoutPhotoSection
