import { get } from 'lodash'
import { useCallback } from 'react'
import { connect } from 'react-redux'
import { CustomText, Modal } from '../../../../../components'
import AmountTitle from '../../../../../components/AmountTitle'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../lang'
import { UnderPaymentModalStyle } from './index.style'
import AuthActions from '../../../../../redux/auth/action'
import AgentActions from '../../../../../redux/user/action'

const { logoutGuardian } = AuthActions
const { getAgentDetails } = AgentActions

function UnderPaymentModal (props) {
  const {
    showModal, onClose,
    logoutGuardian, getAgentDetails,
    history
  } = props

  const handleLogout = useCallback(() => {
    logoutGuardian(true)
  }, [logoutGuardian])

  const handleTheBtnClick = useCallback((type) => {
    if (type === 'uploadPhoto') {
      // click the select photo input to upload the
      // proof from the device
      document.getElementById('photo-upload').click()
    } else if (type === 'logoutPartner') {
      handleLogout()
    }
    onClose()
  }, [onClose, handleLogout])

  const renderButtonTitle = useCallback((title, bottom = '0', type) => {
    return (
      <CustomText
        color={AgentColorPallette.madras}
        weight={800}
        size='16px'
        textAlign='center'
        bottom={bottom}
        className='btn-bottom'
      >
        <span className='cursor' onClick={() => handleTheBtnClick(type)}>{title}</span>
      </CustomText>
    )
  }, [handleTheBtnClick])

  return (
    <Modal isOpen={showModal} onClose={onClose}>
      <UnderPaymentModalStyle>
        <CustomText
          color={AgentColorPallette.darkCharcoal}
          size='16px'
          weight={700}
          bottom='10px'
        >
          {LANG_STRINGS.differenceCalculation}
        </CustomText>
        <AmountTitle
          title={LANG_STRINGS.mustPay}
          amount={get(props, 'data.amountToPay', 0)}
          color={AgentColorPallette.fontDarkerGrey}
          size='10px'
          amountWeight={500}
          className='amount-section-border-top'
        />
        <AmountTitle
          title={LANG_STRINGS.paymentAmount}
          amount={get(props, 'data.paidAmount', 0)}
          color={AgentColorPallette.fontDarkerGrey}
          size='10px'
          amountWeight={500}
          className='amount-section-border-top'
        />
        <AmountTitle
          title={LANG_STRINGS.difference}
          amount={get(props, 'data.amountToPay', 0) - get(props, 'data.paidAmount', 0)}
          color={AgentColorPallette.fontDarkerGrey}
          size='10px'
          titleWeight={700}
          amountColor={AgentColorPallette.blood}
          className='amount-section-border-top'
        />
        <CustomText color={AgentColorPallette.fontDarkerGrey} size='14px' bottom='10px' top='10px'>
          {LANG_STRINGS.underPaymentNotificationText}
        </CustomText>
        <CustomText color={AgentColorPallette.fontDarkerGrey} size='10px' bottom='20px'>
          {LANG_STRINGS.overPaymentDifferenceAddToWallet}
        </CustomText>
        {renderButtonTitle(LANG_STRINGS.uploadNewPhoto, '0', 'uploadPhoto')}
        {renderButtonTitle(LANG_STRINGS.logoutAsPartner, '0', 'logoutPartner')}
      </UnderPaymentModalStyle>
    </Modal>
  )
}

export default connect((state) => ({

}), {
  logoutGuardian,
  getAgentDetails
})(UnderPaymentModal)
