import { useState, useRef, useCallback, useEffect } from 'react'
import { MitraCard, Row } from '../../../../../commonStyle/index.style'
import { CustomText } from '../../../../../components'
import ButtonWithIcon from '../../../../../components/ButtonWithIcon'
import moment from 'moment'
// import DobInput from '../../../../../components/DobInput'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { SEND_GOLD_ICON } from '../../../../../images'
import { ERROR_LANG, LANG_STRINGS } from '../../../../../lang'
import { AdditionalInfoStyle, DatePickerStyle } from './index.style'
import { Datepicker } from '@mobiscroll/react'

function AdditionalInfoSheet (props) {
  const { data = {}, onApply, additionalInfo = {} } = props
  const [selectedPaidTo, setSelectedPaidTo] = useState()
  // const [paymentDateError] = useState('')
  const [errorObj, setErrorObj] = useState({
    paidTo: false,
    paymentDate: false
  })
  const dateRef = useRef(null)
  const isSetPaidTo = useRef(null)
  const dateValue = useRef()

  const handlePaymentDate = useCallback((date) => {
    // handle payment date enter by Agent
    dateValue.current = date.valueText
    setErrorObj({
      ...errorObj,
      paymentDate: false
    })
  }, [setErrorObj, dateValue,
    errorObj
  ])

  useEffect(() => {
    if (data.application_no && !selectedPaidTo && !isSetPaidTo.current && additionalInfo.paymentPaidTo) {
      isSetPaidTo.current = true
      setSelectedPaidTo(additionalInfo.paymentPaidTo)
    }
  }, [data, additionalInfo.paymentPaidTo,
    selectedPaidTo, dateValue
  ])

  const handleReset = useCallback(() => {
    setSelectedPaidTo('')
    // dateRef.current.resetDate()
  }, [])

  const handleTheApply = useCallback(() => {
    // handle the apply
    if (dateRef.current.state.showError) {
      return
    }
    if (!dateValue.current || !selectedPaidTo) {
      setErrorObj({
        paidTo: !selectedPaidTo,
        paymentDate: !dateValue.current
      })
      return
    }
    handleReset()
    onApply({
      [data.application_no]: {
        date: dateValue.current,
        paymentPaidTo: selectedPaidTo
      }
    })
    dateValue.current = ''
    isSetPaidTo.current = null
  }, [data, selectedPaidTo, onApply, handleReset])

  const handleSelectedPaidTo = (type) => {
    setSelectedPaidTo(type)
    setErrorObj({
      ...errorObj,
      paidTo: false
    })
  }

  const renderSelectPaidTo = (title, type) => {
    return (
      <CustomText
        color={AgentColorPallette.black}
        className={`paid-to-section ${type === selectedPaidTo ? 'selected-paid-type' : ''}`}
        onClick={() => handleSelectedPaidTo(type)}
      >
        {title}
      </CustomText>
    )
  }

  return (
    <AdditionalInfoStyle>
      <Row align='center' justify='space-between'>
        <CustomText color={AgentColorPallette.black} weight={700} size='16px'>
          {LANG_STRINGS.additionalInfo}
        </CustomText>
        <CustomText className='cursor' color={AgentColorPallette.blood} size='14px' onClick={handleReset}>
          {LANG_STRINGS.reset}
        </CustomText>
      </Row>
      <MitraCard width='auto' bottom='8px'>
        <CustomText color={AgentColorPallette.black} weight={700} size='16px' bottom='8px'>
          {LANG_STRINGS.paidTo}
        </CustomText>
        <Row align='center'>
          {
            renderSelectPaidTo(LANG_STRINGS.futureMitra, 'FUTURA')
          }
          &nbsp;&nbsp;&nbsp;
          {
            renderSelectPaidTo(LANG_STRINGS.insuranceCompany, 'PROVIDER')
          }
        </Row>
        {
          errorObj.paidTo && (
            <CustomText color={AgentColorPallette.errorDark} size='10px'>
              {ERROR_LANG.pleaseSelectPaidTo}
            </CustomText>
          )
        }
      </MitraCard>
      <MitraCard width='auto'>
        <CustomText color={AgentColorPallette.black} weight={700} size='16px' bottom='8px'>
          {LANG_STRINGS.paymentDate}
        </CustomText>
        {/* <DobInput
          errorField={paymentDateError}
          name='paymentDate'
          ref={dateRef}
          showCalenderIcon
          onDobSelect={handlePaymentDate}
          displayBorder
          borderColor={AgentColorPallette.borderGrey}
          defaultValue={additionalInfo.date}
          errorMsg={ERROR_LANG.pleaseEnterTodayDateOrPreviousDate}
          maxDate={new Date()}
        /> */}
        <DatePickerStyle error={errorObj.paymentDate}>
          <Datepicker
            ref={dateRef}
            theme='ios'
            themeVariant='light'
            touchUi
            controls={['date']}
            dateFormat='DD/MM/YYYY'
            inputComponent='input'
            max={moment()}
            className='calendar'
            inputProps={{
              placeholder: 'DD/MM/YYYY',
              className: 'calendar input-calendar-icon'
            }}
            defaultValue={additionalInfo.date}
            onChange={handlePaymentDate}
          />
        </DatePickerStyle>
        {
          errorObj.paymentDate && (
            <CustomText color={AgentColorPallette.errorDark} size='10px'>
              {ERROR_LANG.pleaseSelectPaymentDate}
            </CustomText>
          )
        }
      </MitraCard>
      <ButtonWithIcon
        text={LANG_STRINGS.apply}
        icon={SEND_GOLD_ICON}
        iconRight
        onClick={handleTheApply}
      />
    </AdditionalInfoStyle>
  )
}

export default AdditionalInfoSheet
