import { get, isEmpty } from 'lodash'
import moment from 'moment'
import { useCallback, useState, useRef, useEffect } from 'react'
import { BottomActionContainerStyle } from '../../../../../../commonStyle/index.style'
import { Container } from '../../../../../../components'
import AmountTitle from '../../../../../../components/AmountTitle'
import BottomActionSheet from '../../../../../../components/BottomActionSheet'
import ButtonWithIcon from '../../../../../../components/ButtonWithIcon'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { SEND_GOLD_ICON } from '../../../../../../images'
import { LANG_STRINGS, ERROR_LANG } from '../../../../../../lang'
import AdditionalInfoSheet from '../../../components/AdditionalInfoSheet'
import OfflinePolicyCard from '../../../components/OfflinePolicyCard'
import PayoutPhotoSection from '../../../components/PayoutPhotoSection'
import { PayoutProofStyle } from './index.style'
import { useResetInstantPayoutState, useSubmitPoliciesProof, useUpdateAdditionalInfo, useGetProof } from '../../../state/hooks/useInstantPayout'
import ConfirmationModal from '../../../../../../components/ConfirmationModal'
import { useErrorContextValue, useLoaderContextValue, resetError } from '@pasarpolis/common-react-hooks'
import { getFromLocalStorageData, removeFromLocalStorageData } from '../../../../../../helpers/localstorage'
import { LOGIN_AS_GURDIAN, PROOF_ID } from '../../../../../../constants/cookies'
import UnderPaymentModal from '../../../components/UnderPaymentModal'
import Cookies from 'universal-cookie'
import { OVERPAYMENT_UNDER_PREMIUM } from '../../../constants'
import { useGlobalContextValue } from '../../../../../../contextProvider/GlobalContext'
import ShowSnackbar from '../../../../../../components/ShowNotification'
const cookies = new Cookies()

function InstantPayoutProofContainer (props) {
  const { location, history } = props
  const [policies = []] = useState(Object.values(get(location, 'state.policies', {})))
  const [totalBill, setTotalBill] = useState(Math.round(get(location, 'state.totalBill', 0)))
  const [showBottomSheet, setShowBottomSheet] = useState(false)
  const [showErrorBorder, setErrorBorder] = useState(false)
  const [amountPaidError, setAmountPaidError] = useState('')
  const [confirmationPolicy, setConfirmationPolicy] = useState({})
  const bottomSheetData = useRef({})
  const [showUnderPaymentModal, setShowUnderPaymentModal] = useState(false)
  const [{
    additionalPoliciesInfo = {}, policiesAmount, uploadProofPhotoData
  }, updatePolicyInfo] = useUpdateAdditionalInfo()
  const [{ SUBMIT_PROOF_ERROR, submitProofStatus, getProofStatus, GET_PROOF_ERROR }, dispatchError] = useErrorContextValue()
  const [{ UPLOAD_PROOF_PHOTO_LOADER, SUBMIT_PROOF_LOADER, GET_PROOF_LOADER }] = useLoaderContextValue()
  const resetInstantState = useResetInstantPayoutState()
  const [{ submitProofData = {} }, submitProofRequest] = useSubmitPoliciesProof()
  const [{ getProofData = {} }, getProofRequest] = useGetProof()
  const [{ getAgentDetailData }] = useGlobalContextValue()

  const that = useRef({ isProofReqCall: false })

  useEffect(() => {
    const proofId = getFromLocalStorageData(PROOF_ID)
    if (proofId && (typeof proofId === 'string') && !that.current.isProofReqCall) {
      getProofRequest({ proofId })
      that.current.isProofReqCall = true
    } else if (!get(policies, 'length', 0)) {
      history.replace('/instant/payout/transactions')
    }
  }, [getProofRequest, policies, history])

  useEffect(() => {
    if (getProofStatus === 'success') {
      const applicationNo = get(policies, '[0].application_no', '')
      const paidTo = get(getProofData, 'policy_application.paid_to', '')
      let paymentDate = get(getProofData, 'policy_application.payment_date', '')
      if (paymentDate) {
        paymentDate = moment(paymentDate, 'YYYY-MM-DD').format('DD-MM-YYYY')
      }
      if (applicationNo && paymentDate && paidTo) {
        updatePolicyInfo({
          [applicationNo]: { date: paymentDate, paymentPaidTo: paidTo }
        })
      }
      dispatchError(resetError({
        getProofStatus: ''
      }))
    } else if (GET_PROOF_ERROR && getProofStatus && getProofStatus !== 'success') {
      ShowSnackbar.error({
        visible: true,
        text: getProofStatus
      })
      dispatchError(resetError({
        getProofStatus: ''
      }))
    }
  }, [GET_PROOF_ERROR, getProofStatus,
    dispatchError, policies, updatePolicyInfo,
    getProofData
  ])

  useEffect(() => {
    return () => {
      removeFromLocalStorageData(PROOF_ID)
    }
  }, [])

  useEffect(() => {
    if (SUBMIT_PROOF_ERROR && submitProofStatus && (submitProofStatus !== 'success')) {
      ShowSnackbar.error({
        visible: true,
        text: submitProofStatus
      })
      dispatchError(resetError({
        submitProofStatus: ''
      }))
      // resetInstantState(['submitProofStatus'])
    } else if (submitProofStatus === 'success') {
      if (totalBill > policiesAmount) {
        history.push(`/instant/payout/underpayment/${submitProofData.id}`)
        dispatchError(resetError({
          submitProofStatus: ''
        }))
      } else {
        const actualPremium = policies[0].premium
        const paymentBy = policies[0].payment_by
        let scenario = 'OVERPAYMENT'
        if (paymentBy === 'AGENT' && policiesAmount < actualPremium) {
          scenario = OVERPAYMENT_UNDER_PREMIUM
        }

        const discount = submitProofData.discount
        const totalPolicyCommission = submitProofData.total_policy_commission - discount

        const commissionCreditedToWallet = totalPolicyCommission -
        submitProofData.policy_commission_used -
        submitProofData.policy_commission_tax

        history.replace({
          pathname: '/instant/payout/confirmation',
          state: {
            scenario,
            totalBill: scenario === OVERPAYMENT_UNDER_PREMIUM ? submitProofData.customer_total_premium : totalBill,
            amountPaid: policiesAmount,
            overPayment: (policiesAmount - totalBill),
            totalCommission: totalPolicyCommission,
            commissionUsed: submitProofData.policy_commission_used,
            taxOnCommission: submitProofData.policy_commission_tax,
            commissionCreditedToWallet: commissionCreditedToWallet
          }
        })
        dispatchError(resetError({
          submitProofStatus: ''
        }))
      }
    }
  }, [
    submitProofStatus, resetInstantState, SUBMIT_PROOF_ERROR,
    history, policiesAmount, totalBill, dispatchError, submitProofData,
    policies
  ])

  const handleAdditionalInfo = useCallback((policy) => {
    setShowBottomSheet(!showBottomSheet)
    bottomSheetData.current = policy
  }, [showBottomSheet])

  const handleCloseUnderPaymentModal = () => {
    setShowUnderPaymentModal(false)
  }

  const handleSendProof = useCallback(() => {
    // setShowUnderPaymentModal(!showUnderPaymentModal)
    // this is the api call to submit data
    if (!getAgentDetailData.is_ktp_verified && (policies[0].payment_by === 'AGENT')) {
      if (ShowSnackbar.error) {
        ShowSnackbar.error({
          visible: true,
          text: LANG_STRINGS.yourKtpMustVerifiedForThePayment
        })
      }
      return
    }

    if (isEmpty(additionalPoliciesInfo)) {
      setErrorBorder(true)
      ShowSnackbar.error({
        visible: true,
        text: ERROR_LANG.enterPolicyAdditionInfo
      })
      return
    }

    if (!policiesAmount) {
      // this for the payment input if input field is empty
      setAmountPaidError('paymentAmount')
      ShowSnackbar.error({
        visible: true,
        text: ERROR_LANG.pleaseEnterPaymentAmount
      })
      return
    }
    if (amountPaidError) {
      setAmountPaidError('')
    }

    if (!get(uploadProofPhotoData, 'length', 0)) {
      ShowSnackbar.error({
        visible: true,
        text: ERROR_LANG.pleaseUploadPhotoOfProof
      })
      return
    }
    const isGuardianAgentLogin = cookies.get(LOGIN_AS_GURDIAN)
    if ((totalBill > policiesAmount) && isGuardianAgentLogin) {
      setShowUnderPaymentModal(true)
      return
    }

    if (totalBill !== parseInt(policiesAmount)) {
      ShowSnackbar.error({
        visible: true,
        text: ERROR_LANG.pleaseEnterPaymentInvoice
      })
      return
    }

    const data = {
      body: {
        policy_application: policies.map(policy => {
          const policyInfo = get(additionalPoliciesInfo, `${policy.application_no}`, {})
          return {
            id: policy.id,
            paid_by: policy.payment_by,
            paid_to: policyInfo.paymentPaidTo,
            payment_date: moment(policyInfo.date, 'DD/MM/YYYY').format('YYYY-MM-DD')
          }
        }),
        amount_paid: policiesAmount,
        doc_urls: uploadProofPhotoData.map((url) => ({ url }))
      }
    }

    const proofId = getFromLocalStorageData(PROOF_ID)
    if (proofId && (typeof proofId === 'string')) {
      data.body.id = proofId
    }
    submitProofRequest(data)
  }, [
    submitProofRequest, policiesAmount, uploadProofPhotoData,
    policies, additionalPoliciesInfo, amountPaidError,
    setShowUnderPaymentModal, totalBill, getAgentDetailData.is_ktp_verified
  ])

  const handleOnApply = useCallback((data = {}) => {
    // handle the form element
    setShowBottomSheet(false)
    updatePolicyInfo(data)
    bottomSheetData.current = {}
  }, [setShowBottomSheet, updatePolicyInfo])

  const handleCheckbox = useCallback((policy, index, removeCallback) => {
    // store the index and policy id to store so that remove of policy
    // remains easy
    setConfirmationPolicy({
      applicationNo: policy.application_no,
      removeCallback,
      index
    })
  }, [])

  const handleCloseConfirmation = useCallback(() => {
    setConfirmationPolicy({})
  }, [])

  const handleConfirmationAgree = useCallback(() => {
    confirmationPolicy.removeCallback(false)
    const removePolicy = policies.splice(confirmationPolicy.index, 1)[0]
    setConfirmationPolicy(policies)
    // update the totalBill if the policy is remove from the store
    setTotalBill(totalBill - get(removePolicy, `breakup.[${removePolicy.payment_by.toLowerCase()}].net_payable`, 0))
  }, [policies, totalBill, confirmationPolicy])

  return (
    <Container
      title={LANG_STRINGS.proofOfPayment}
      loader={UPLOAD_PROOF_PHOTO_LOADER || SUBMIT_PROOF_LOADER || GET_PROOF_LOADER}
      hideBottomTabs
    >
      <PayoutProofStyle>
        <AmountTitle
          title={`A. ${LANG_STRINGS.totalBill}`}
          titleWeight={800}
          size='15px'
          amount={totalBill}
          amountColor={AgentColorPallette.blood}
        />
        {
          policies.map((policy, index) => (
            <OfflinePolicyCard
              key={policy.id}
              policy={policy}
              additionalInfo={additionalPoliciesInfo[policy.application_no]}
              isShowErrorBorder={showErrorBorder && !additionalPoliciesInfo[policy.application_no]}
              showAdditionalInfo
              disabledPaidBy
              onAdditionalInfoClick={handleAdditionalInfo}
              hideCheckbox={policies.length === 1}
              onCheckboxClick={(checkboxCallback) => handleCheckbox(policy, index, checkboxCallback)}
            />
          ))
        }
        <div className='separator' />
        <PayoutPhotoSection prefilledData={getProofData} errorField={amountPaidError} />
        <BottomActionContainerStyle padding='0'>
          <ButtonWithIcon
            text={LANG_STRINGS.send}
            icon={SEND_GOLD_ICON}
            className='send-proof-btn'
            iconRight
            onClick={handleSendProof}
          />
        </BottomActionContainerStyle>
      </PayoutProofStyle>
      <BottomActionSheet show={showBottomSheet} onCloseSheet={() => setShowBottomSheet(false)}>
        <AdditionalInfoSheet
          prefilledData={getProofData}
          data={bottomSheetData.current}
          additionalInfo={additionalPoliciesInfo[get(bottomSheetData, 'current.application_no', '')]}
          onApply={handleOnApply}
        />
      </BottomActionSheet>
      <UnderPaymentModal
        showModal={showUnderPaymentModal}
        onClose={handleCloseUnderPaymentModal}
        history={history}
        data={{
          amountToPay: totalBill,
          paidAmount: policiesAmount
        }}
      />
      <ConfirmationModal
        showModal={confirmationPolicy.applicationNo}
        onClose={handleCloseConfirmation}
        agreeText={LANG_STRINGS.yes}
        confirmText={`${LANG_STRINGS.areYouSureYouWantToRemovePolicy} ${confirmationPolicy.applicationNo}`}
        modelTitle={LANG_STRINGS.information}
        onAgree={handleConfirmationAgree}
      />
      <ShowSnackbar hideOkay />
    </Container>
  )
}

export default InstantPayoutProofContainer
